 import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, DirectionalLight, AmbientLight, PointLight, Vector3, Color } = THREE;

  // Resolve colors
  const ink = new Color(config.intent?.visualSpec?.colors?.ink ?? '#16161d');
  const paper = new Color(config.intent?.visualSpec?.colors?.paper ?? '#e8ecf2');
  const accent = new Color(config.intent?.visualSpec?.colors?.accent ?? '#ff2a38');
  const surface = new Color(config.intent?.visualSpec?.colors?.surface ?? '#0b0b10');

  const root = new Group();
  root.name = 'home-thumbnail-root';

  const liftGroup = new Group();
  liftGroup.name = 'home-thumbnail-lift';
  root.add(liftGroup);

  // Backdrop stage plane
  const backdropGeo = new PlaneGeometry(7.2, 4.8, 1, 1);
  const backdropMat = new MeshStandardNodeMaterial({
    color: surface,
    roughness: 0.75,
    metalness: 0.12,
    emissive: ink,
    emissiveIntensity: 0.15
  });
  // Vertical gradient via node shader: blend ink -> surface
  const vUv = uv();
  const gradFactor = smoothstep(0.0, 1.0, vUv.y);
  backdropMat.colorNode = mix(vec3(color(ink)), vec3(color(surface)), gradFactor);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  backdrop.receiveShadow = true;
  liftGroup.add(backdrop);

  // Accent edge strip
  const edgeGeo = new PlaneGeometry(7.3, 0.04);
  const edgeMat = new MeshStandardNodeMaterial({
    color: accent,
    emissive: accent,
    emissiveIntensity: 1.6,
    roughness: 0.9,
    metalness: 0.0
  });
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.set(0, -2.35, -2.45);
  liftGroup.add(edge);

  // Lighting
  const ambient = new AmbientLight(paper, 0.65);
  liftGroup.add(ambient);

  const key = new DirectionalLight(paper, 1.2);
  key.position.set(3, 3, 6);
  key.target.position.set(0, 0, 0);
  liftGroup.add(key);
  liftGroup.add(key.target);

  const rim = new DirectionalLight(accent, 0.75);
  rim.position.set(-4, 2, -3);
  rim.target.position.set(0, 0, 0);
  liftGroup.add(rim);
  liftGroup.add(rim.target);

  const fill = new DirectionalLight(paper, 0.45);
  fill.position.set(0, -3, 4);
  fill.target.position.set(0, 0, 0);
  liftGroup.add(fill);
  liftGroup.add(fill.target);

  const timelines = [];

  // Contact shadow plane
  const shadowGeo = new PlaneGeometry(2.2, 2.2);
  const shadowMat = new MeshStandardNodeMaterial({
    color: new Color(0x000000),
    transparent: true,
    opacity: 0.5,
    roughness: 1.0,
    metalness: 0.0
  });
  const shadowPlane = new Mesh(shadowGeo, shadowMat);
  shadowPlane.rotation.x = -Math.PI / 2;
  shadowPlane.position.set(0, -1.9, 0);
  liftGroup.add(shadowPlane);

  // GLB load
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const scene = gltf.scene;
      scene.name = 'home-gear-showpiece';

      scene.traverse((child) => {
        if (child.isMesh) {
          child.castShadow = true;
          child.receiveShadow = true;
          if (child.material) {
            if (Array.isArray(child.material)) {
              child.material.forEach((m) => {
                if (typeof m.dispose === 'function') m.needsUpdate = true;
              });
            } else {
              child.material.needsUpdate = true;
            }
          }
        }
      });

      // Frame to 60% of hub height, centered
      const box = new THREE.Box3().setFromObject(scene);
      const size = new THREE.Vector3();
      box.getSize(size);
      const maxDim = Math.max(size.x, size.y, size.z);
      const desiredHeight = 3.9;
      const scale = desiredHeight / maxDim;
      scene.scale.setScalar(scale);
      const center = new THREE.Vector3();
      box.getCenter(center);
      scene.position.sub(center.multiplyScalar(scale));
      scene.position.y += 0.25;

      liftGroup.add(scene);

      // Gentle idle rotation
      const idleTl = gsap.to(scene.rotation, {
        y: Math.PI * 2,
        duration: 22,
        repeat: -1,
        ease: 'none'
      });
      timelines.push(idleTl);
    });
  }

  // Interaction timelines
  let hoverTl = null;
  let pressTl = null;

  const baseY = liftGroup.position.y;

  function onHover(over) {
    if (hoverTl) { hoverTl.kill(); hoverTl = null; }
    hoverTl = gsap.to(liftGroup.position, {
      y: over ? baseY + 0.15 : baseY,
      duration: 0.35,
      ease: 'power2.out'
    });
    timelines.push(hoverTl);
  }

  function onPress(down) {
    if (pressTl) { pressTl.kill(); pressTl = null; }
    pressTl = gsap.to(liftGroup.scale, {
      x: down ? 0.97 : 1,
      y: down ? 0.97 : 1,
      z: down ? 0.97 : 1,
      duration: 0.12,
      ease: 'back.out(1.2)'
    });
    timelines.push(pressTl);
  }

  function onClick() {
    onPress(true);
    setTimeout(() => onPress(false), 140);
    ctx.emit('hub-home.select', { id: config.id, node: config });
  }

  root.userData.handlers = {
    hover: onHover,
    press: onPress,
    click: onClick
  };

  root.userData.cleanup = () => {
    timelines.forEach((tl) => { if (tl && tl.kill) tl.kill(); });
    liftGroup.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => { if (m && m.dispose) m.dispose(); });
        } else if (obj.material.dispose) {
          obj.material.dispose();
        }
      }
      if (obj.texture && obj.texture.dispose) obj.texture.dispose();
    });
  };

  return root;
}
